-- SmartPark initial schema. Run only against a new SmartPark database.
-- UUID identifiers are generated by the application layer.

CREATE TABLE IF NOT EXISTS users (
  id CHAR(36) PRIMARY KEY,
  full_name VARCHAR(120) NOT NULL,
  email VARCHAR(254) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  phone VARCHAR(30) NULL,
  account_status ENUM('pending_verification','active','suspended','deleted') NOT NULL DEFAULT 'pending_verification',
  email_verified_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_users_status (account_status)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS roles (
  id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  role_key VARCHAR(40) NOT NULL UNIQUE,
  display_name VARCHAR(80) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS user_roles (
  user_id CHAR(36) NOT NULL,
  role_id SMALLINT UNSIGNED NOT NULL,
  assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, role_id),
  CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id) REFERENCES users(id),
  CONSTRAINT fk_user_roles_role FOREIGN KEY (role_id) REFERENCES roles(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS vehicles (
  id CHAR(36) PRIMARY KEY,
  owner_user_id CHAR(36) NOT NULL,
  registration_number VARCHAR(24) NOT NULL,
  make VARCHAR(80) NULL,
  model VARCHAR(80) NULL,
  vehicle_type ENUM('motorcycle','car','suv','van','truck','other') NOT NULL DEFAULT 'car',
  color VARCHAR(40) NULL,
  model_year SMALLINT UNSIGNED NULL,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_vehicle_registration (registration_number),
  INDEX idx_vehicles_owner (owner_user_id),
  CONSTRAINT fk_vehicles_owner FOREIGN KEY (owner_user_id) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS parking_lots (
  id CHAR(36) PRIMARY KEY,
  owner_user_id CHAR(36) NULL,
  name VARCHAR(160) NOT NULL,
  description TEXT NULL,
  address_line VARCHAR(255) NOT NULL,
  city VARCHAR(100) NOT NULL,
  region VARCHAR(100) NULL,
  postal_code VARCHAR(20) NULL,
  country_code CHAR(2) NULL,
  latitude DECIMAL(10,7) NULL,
  longitude DECIMAL(10,7) NULL,
  timezone VARCHAR(64) NOT NULL DEFAULT 'UTC',
  currency CHAR(3) NOT NULL DEFAULT 'INR',
  opening_time TIME NULL,
  closing_time TIME NULL,
  facility_status ENUM('draft','pending_approval','active','paused','closed','archived') NOT NULL DEFAULT 'draft',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_lots_status_city (facility_status, city),
  INDEX idx_lots_owner (owner_user_id),
  CONSTRAINT fk_lots_owner FOREIGN KEY (owner_user_id) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS parking_zones (
  id CHAR(36) PRIMARY KEY,
  parking_lot_id CHAR(36) NOT NULL,
  name VARCHAR(80) NOT NULL,
  level_label VARCHAR(40) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_zone_name (parking_lot_id, name),
  CONSTRAINT fk_zones_lot FOREIGN KEY (parking_lot_id) REFERENCES parking_lots(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS parking_slots (
  id CHAR(36) PRIMARY KEY,
  parking_lot_id CHAR(36) NOT NULL,
  zone_id CHAR(36) NULL,
  slot_code VARCHAR(30) NOT NULL,
  vehicle_type ENUM('motorcycle','car','suv','van','truck','other','any') NOT NULL DEFAULT 'any',
  covered BOOLEAN NOT NULL DEFAULT FALSE,
  accessible BOOLEAN NOT NULL DEFAULT FALSE,
  operational_status ENUM('open','disabled','maintenance') NOT NULL DEFAULT 'open',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_slot_code (parking_lot_id, slot_code),
  INDEX idx_slots_lot_status (parking_lot_id, operational_status),
  CONSTRAINT fk_slots_lot FOREIGN KEY (parking_lot_id) REFERENCES parking_lots(id),
  CONSTRAINT fk_slots_zone FOREIGN KEY (zone_id) REFERENCES parking_zones(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS pricing_rules (
  id CHAR(36) PRIMARY KEY,
  parking_lot_id CHAR(36) NOT NULL,
  slot_id CHAR(36) NULL,
  rate_type ENUM('hourly','daily','weekly','monthly') NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  currency CHAR(3) NOT NULL DEFAULT 'INR',
  service_fee DECIMAL(12,2) NOT NULL DEFAULT 0,
  tax_rate_percent DECIMAL(5,2) NOT NULL DEFAULT 0,
  valid_from DATETIME NULL,
  valid_until DATETIME NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_pricing_lot_active (parking_lot_id, is_active, rate_type),
  CONSTRAINT fk_pricing_lot FOREIGN KEY (parking_lot_id) REFERENCES parking_lots(id),
  CONSTRAINT fk_pricing_slot FOREIGN KEY (slot_id) REFERENCES parking_slots(id),
  CONSTRAINT chk_pricing_amount CHECK (amount >= 0),
  CONSTRAINT chk_pricing_fee CHECK (service_fee >= 0),
  CONSTRAINT chk_pricing_tax CHECK (tax_rate_percent >= 0 AND tax_rate_percent <= 100)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS bookings (
  id CHAR(36) PRIMARY KEY,
  booking_code VARCHAR(32) NOT NULL UNIQUE,
  user_id CHAR(36) NOT NULL,
  parking_lot_id CHAR(36) NOT NULL,
  slot_id CHAR(36) NOT NULL,
  vehicle_id CHAR(36) NULL,
  start_at DATETIME NOT NULL,
  end_at DATETIME NOT NULL,
  status ENUM('held','pending_payment','confirmed','checked_in','completed','cancelled','expired','payment_failed') NOT NULL DEFAULT 'held',
  hold_expires_at DATETIME NULL,
  currency CHAR(3) NOT NULL DEFAULT 'INR',
  base_amount DECIMAL(12,2) NOT NULL DEFAULT 0,
  service_fee DECIMAL(12,2) NOT NULL DEFAULT 0,
  tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0,
  discount_amount DECIMAL(12,2) NOT NULL DEFAULT 0,
  total_amount DECIMAL(12,2) NOT NULL DEFAULT 0,
  pricing_snapshot JSON NULL,
  qr_token_hash VARCHAR(255) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_bookings_user_created (user_id, created_at),
  INDEX idx_bookings_slot_interval (slot_id, start_at, end_at, status),
  INDEX idx_bookings_lot_status (parking_lot_id, status),
  CONSTRAINT fk_bookings_user FOREIGN KEY (user_id) REFERENCES users(id),
  CONSTRAINT fk_bookings_lot FOREIGN KEY (parking_lot_id) REFERENCES parking_lots(id),
  CONSTRAINT fk_bookings_slot FOREIGN KEY (slot_id) REFERENCES parking_slots(id),
  CONSTRAINT fk_bookings_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
  CONSTRAINT chk_booking_interval CHECK (end_at > start_at),
  CONSTRAINT chk_booking_total CHECK (total_amount >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS parking_sessions (
  id CHAR(36) PRIMARY KEY,
  booking_id CHAR(36) NULL,
  parking_lot_id CHAR(36) NOT NULL,
  slot_id CHAR(36) NOT NULL,
  vehicle_id CHAR(36) NULL,
  ticket_code VARCHAR(32) NOT NULL UNIQUE,
  entry_source ENUM('qr','attendant','manual','other') NOT NULL DEFAULT 'attendant',
  entered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  exited_at DATETIME NULL,
  status ENUM('parked','exited','exception') NOT NULL DEFAULT 'parked',
  notes VARCHAR(500) NULL,
  INDEX idx_sessions_active (parking_lot_id, status, entered_at),
  CONSTRAINT fk_sessions_booking FOREIGN KEY (booking_id) REFERENCES bookings(id),
  CONSTRAINT fk_sessions_lot FOREIGN KEY (parking_lot_id) REFERENCES parking_lots(id),
  CONSTRAINT fk_sessions_slot FOREIGN KEY (slot_id) REFERENCES parking_slots(id),
  CONSTRAINT fk_sessions_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS payments (
  id CHAR(36) PRIMARY KEY,
  booking_id CHAR(36) NOT NULL,
  provider VARCHAR(60) NOT NULL,
  provider_order_id VARCHAR(180) NULL,
  provider_payment_id VARCHAR(180) NULL,
  amount DECIMAL(12,2) NOT NULL,
  currency CHAR(3) NOT NULL DEFAULT 'INR',
  status ENUM('created','pending','authorized','paid','failed','cancelled','partially_refunded','refunded') NOT NULL DEFAULT 'created',
  idempotency_key VARCHAR(160) NOT NULL UNIQUE,
  verified_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_provider_payment (provider, provider_payment_id),
  INDEX idx_payments_booking (booking_id, created_at),
  CONSTRAINT fk_payments_booking FOREIGN KEY (booking_id) REFERENCES bookings(id),
  CONSTRAINT chk_payment_amount CHECK (amount >= 0)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS cameras (
  id CHAR(36) PRIMARY KEY,
  parking_lot_id CHAR(36) NOT NULL,
  name VARCHAR(120) NOT NULL,
  stream_reference VARCHAR(500) NULL,
  status ENUM('configured','online','offline','disabled') NOT NULL DEFAULT 'configured',
  last_seen_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_cameras_lot_status (parking_lot_id, status),
  CONSTRAINT fk_cameras_lot FOREIGN KEY (parking_lot_id) REFERENCES parking_lots(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS camera_slot_regions (
  id CHAR(36) PRIMARY KEY,
  camera_id CHAR(36) NOT NULL,
  slot_id CHAR(36) NOT NULL,
  region_coordinates JSON NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_camera_slot (camera_id, slot_id),
  CONSTRAINT fk_regions_camera FOREIGN KEY (camera_id) REFERENCES cameras(id),
  CONSTRAINT fk_regions_slot FOREIGN KEY (slot_id) REFERENCES parking_slots(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS occupancy_events (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  camera_id CHAR(36) NOT NULL,
  slot_id CHAR(36) NOT NULL,
  observed_state ENUM('empty','occupied','unknown') NOT NULL,
  confidence DECIMAL(5,4) NULL,
  observed_at DATETIME(3) NOT NULL,
  received_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  source ENUM('camera','operator','system') NOT NULL DEFAULT 'camera',
  INDEX idx_occupancy_slot_time (slot_id, observed_at),
  INDEX idx_occupancy_camera_time (camera_id, observed_at),
  CONSTRAINT fk_occupancy_camera FOREIGN KEY (camera_id) REFERENCES cameras(id),
  CONSTRAINT fk_occupancy_slot FOREIGN KEY (slot_id) REFERENCES parking_slots(id),
  CONSTRAINT chk_occupancy_confidence CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1))
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS notifications (
  id CHAR(36) PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  channel ENUM('in_app','email','sms','push') NOT NULL DEFAULT 'in_app',
  event_type VARCHAR(80) NOT NULL,
  title VARCHAR(160) NOT NULL,
  message VARCHAR(1000) NOT NULL,
  delivery_status ENUM('queued','sent','failed','read') NOT NULL DEFAULT 'queued',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  read_at DATETIME NULL,
  INDEX idx_notifications_user_status (user_id, delivery_status, created_at),
  CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS audit_logs (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  actor_user_id CHAR(36) NULL,
  action VARCHAR(100) NOT NULL,
  entity_type VARCHAR(80) NOT NULL,
  entity_id VARCHAR(80) NULL,
  request_id VARCHAR(80) NULL,
  metadata JSON NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_audit_entity (entity_type, entity_id, created_at),
  INDEX idx_audit_actor (actor_user_id, created_at),
  CONSTRAINT fk_audit_actor FOREIGN KEY (actor_user_id) REFERENCES users(id)
) ENGINE=InnoDB;

INSERT INTO roles (role_key, display_name) VALUES
  ('driver', 'Driver'),
  ('host', 'Parking Host'),
  ('attendant', 'Parking Attendant'),
  ('operator', 'Facility Operator'),
  ('admin', 'Administrator')
ON DUPLICATE KEY UPDATE display_name = VALUES(display_name);
